#include <iostream>
#include <vector>
#include <unordered_map>
#include <cassert>
#include <chrono>
#include <cstdint>
#include <algorithm>
#include <functional>
using namespace std;

const int MOD = 1000000007;

struct mod_int {
    int val;
    mod_int(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = v;
    }
    explicit operator int() const { return val; }
    mod_int& operator+=(const mod_int &o) { val = (val + o.val) % MOD; return *this; }
    mod_int& operator-=(const mod_int &o) { val = (val - o.val + MOD) % MOD; return *this; }
    mod_int& operator*=(const mod_int &o) { val = (long long)val * o.val % MOD; return *this; }
    mod_int& operator/=(const mod_int &o) { return *this *= o.inv(); }
    mod_int operator-() const { return val ? MOD - val : 0; }
    bool operator==(const mod_int &o) const { return val == o.val; }
    bool operator!=(const mod_int &o) const { return val != o.val; }
    mod_int inv() const {
        int a = val, b = MOD, x = 0, y = 1;
        while (a > 1) {
            int q = a / b;
            a %= b; swap(a, b);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + MOD : x;
    }
    mod_int pow(long long p) const {
        mod_int res(1), a(*this);
        while (p) {
            if (p & 1) res *= a;
            a *= a;
            p >>= 1;
        }
        return res;
    }
    friend mod_int operator+(mod_int a, const mod_int &b) { return a += b; }
    friend mod_int operator-(mod_int a, const mod_int &b) { return a -= b; }
    friend mod_int operator*(mod_int a, const mod_int &b) { return a *= b; }
    friend mod_int operator/(mod_int a, const mod_int &b) { return a /= b; }
};

struct safe_hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }
    uint64_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * ((uint64_t)(new char) | 1));
        return splitmix64(x ^ FIXED_RANDOM);
    }
};

const int N_MAX = 10;
int N;
mod_int probability[N_MAX][N_MAX];

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p; cin >> p;
            probability[i][j] = mod_int(p) / mod_int(100);
        }

    vector<vector<int>> masks_with_count(N + 1);
    vector<int> lookup(1 << N, -1);
    for (int mask = 0; mask < 1 << N; mask++) {
        int cnt = __builtin_popcount(mask);
        lookup[mask] = masks_with_count[cnt].size();
        masks_with_count[cnt].push_back(mask);
    }

    unordered_map<long long, mod_int, safe_hash> possible_masks;
    possible_masks[1LL << lookup[0]] = mod_int(1);

    for (int left = 0; left < N; left++) {
        unordered_map<long long, mod_int, safe_hash> new_possible_masks;
        vector<mod_int> products(1 << N, mod_int(1));

        for (int current = 0; current < 1 << N; current++) {
            mod_int prod(1);
            for (int right = 0; right < N; right++) {
                if (current >> right & 1)
                    prod *= probability[left][right];
                else
                    prod *= (mod_int(1) - probability[left][right]);
            }
            products[current] = prod;
        }

        vector<long long> new_bits(N, 0);
        vector<long long> new_possible(1 << N, 0);

        for (auto &kv : possible_masks) {
            long long possible = kv.first;
            mod_int prob_val = kv.second;

            fill(new_bits.begin(), new_bits.end(), 0);
            for (int mask : masks_with_count[left]) {
                if (possible >> lookup[mask] & 1) {
                    for (int i = 0; i < N; i++) {
                        if ((mask >> i & 1) == 0) {
                            new_bits[i] |= 1LL << lookup[mask | (1 << i)];
                        }
                    }
                }
            }

            new_possible[0] = 0;
            for (int current = 1; current < 1 << N; current++) {
                new_possible[current] = new_possible[current & (current - 1)] | new_bits[__builtin_ctz(current)];
                new_possible_masks[new_possible[current]] += prob_val * products[current];
            }
        }

        possible_masks = move(new_possible_masks);
        cerr << possible_masks.size() << '\n';
    }

    mod_int answer(0);
    int full_mask = (1 << N) - 1;
    for (auto &kv : possible_masks) {
        if (kv.first >> lookup[full_mask] & 1) {
            answer += kv.second;
        }
    }
    cout << (int)answer << '\n';
}
